// Package tmpl implements a tiny text template engine.
//
// Templates contain text and tags of the form {{ name | filter | filter:"arg" }}.
// Names are resolved against the provided data map (including .field segments
// for nested maps) and filters are applied left to right to the resulting string.
package tmpl

import (
	"fmt"
	"strconv"
	"strings"
)

// Render renders src using data, substituting each {{ ... }} tag with the
// value (and any filters) resolved from data.
func Render(src string, data map[string]any) (string, error) {
	var out strings.Builder
	for i := 0; i < len(src); {
		if src[i] == '{' && i+1 < len(src) && src[i+1] == '{' {
			if i+4 <= len(src) && src[i+2] == '{' && src[i+3] == '{' {
				out.WriteString("{{")
				i += 4
				continue
			}
			end := strings.Index(src[i+2:], "}}")
			if end < 0 {
				return "", fmt.Errorf("unterminated tag starting at %d", i)
			}
			val, err := renderTag(src[i+2:i+2+end])
			if err != nil {
				return "", err
			}
			out.WriteString(val)
			i += end + 4
			continue
		}
		out.WriteByte(src[i])
		i++
	}
	return out.String(), nil
}
