func (p *tagParser) applyFilter(s string) (string, error) {
	p.skipSpace()
	fn, err := p.parseIdent()
	if err != nil {
		return "", fmt.Errorf("invalid filter in tag: %v", err)
	}
	spec, ok := filters[fn]
	if !ok {
		return "", fmt.Errorf("unknown filter %q", fn)
	}
	p.skipSpace()
	hasArg := p.i < len(p.s) && p.s[p.i] == ':'
	if hasArg {
		p.i++
		p.skipSpace()
	}
	var arg string
	if hasArg {
		arg, err = p.parseArg()
		if err != nil {
			return "", fmt.Errorf("filter %q: %v", fn, err)
		}
	}
	if spec.needsArg != hasArg {
		verb := "missing"
		if !spec.needsArg {
			verb = "extra"
		}
		return "", fmt.Errorf("filter %q: %s argument", fn, verb)
	}
	if !spec.needsArg {
		return spec.fn(s, "")
	}
	return spec.fn(s, arg)
}
